using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class FinishSevenAssets{
 [Serializable]public class Paths{public string[] paths;}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var race=UnityEngine.Object.FindAnyObjectByType<RaceDirector>();var path="Assets/Resources/WorldMaps/CoursePreviews.json";var catalog=JsonUtility.FromJson<CoursePreviewCatalog>(File.ReadAllText(path));var course=catalog.courses.Single(c=>c.scene=="DansBackyardReverse");course.id=race.courseId;course.main=race.road.points.ToArray();course.branches=UnityEngine.Object.FindObjectsByType<WoodlandRoute>().Select(b=>new CoursePreviewCatalog.Path{points=b.points.ToArray(),undergroundStart=b.undergroundStart,undergroundEnd=b.undergroundEnd}).ToArray();File.WriteAllText(path,JsonUtility.ToJson(catalog,true));var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/VehicleGlazing.mat");mat.SetFloat("_SrcBlend",1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();var used=new HashSet<string>(AssetDatabase.GetDependencies(RacePlaylists.Scenes.Select(s=>"Assets/Scenes/"+s+".unity").ToArray(),true));var candidates=JsonUtility.FromJson<Paths>(File.ReadAllText("Temp/seven-new-assets.json")).paths;var removed=new List<string>();AssetDatabase.StartAssetEditing();try{foreach(var p in candidates)if(!used.Contains(p)){if(!p.StartsWith("Assets/Track/"))throw new Exception("Invalid source cleanup boundary");if(AssetDatabase.DeleteAsset(p))removed.Add(p);}}finally{AssetDatabase.StopAssetEditing();}File.WriteAllLines("Docs/SevenCorrections/removed-intermediate-assets.txt",removed);AssetDatabase.Refresh();return "Updated current course preview, restored glazing import state; removed "+removed.Count+" new unreferenced intermediate mesh/material assets";}
}
